-- M0006 catalogue: tax configuration, categories, brands, clothing products and variants,
-- serialized jewellery items, barcode registry, cost tables.
--
-- NOTHING in this file carries a GST rate, a metal rate or a jewellery pricing rule. Those are
-- client decisions (OQ-01..11) and are configured as data by the owner.

-- ---------------------------------------------------------------------------------------------
-- Tax configuration (no seed data)
-- ---------------------------------------------------------------------------------------------
create table retailos.tax_classes (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null references retailos.tenants (id) on delete restrict,
  code       text not null check (code ~ '^[A-Z0-9_]{1,20}$'),
  name       text not null check (length(btrim(name)) > 0),
  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  unique (tenant_id, id),
  unique (tenant_id, code)
);

create table retailos.tax_rates (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null,
  tax_class_id   uuid not null,
  effective_from date not null,
  effective_to   date,
  gst_rate_pct   numeric(7, 4) not null check (gst_rate_pct >= 0 and gst_rate_pct <= 100),
  created_by     uuid default auth.uid(),
  created_at     timestamptz not null default now(),
  check (effective_to is null or effective_to > effective_from),
  foreign key (tenant_id, tax_class_id) references retailos.tax_classes (tenant_id, id) on delete restrict
);
create index tax_rates_lookup_idx on retailos.tax_rates (tenant_id, tax_class_id, effective_from desc);

-- Rate periods of one class may not overlap. Serialised per class to avoid a write race.
create or replace function retailos_private.tax_rates_no_overlap()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and retailos_private.has_tenant_permission(new.tenant_id, 'tax.manage') is not true then perform retailos_private.fail('FORBIDDEN'); end if;
  perform pg_advisory_xact_lock(hashtextextended(new.tax_class_id::text, 0));
  if exists (
    select 1 from retailos.tax_rates r
    where r.tax_class_id = new.tax_class_id
      and r.id is distinct from new.id
      and daterange(r.effective_from, r.effective_to, '[)') && daterange(new.effective_from, new.effective_to, '[)')
  ) then
    perform retailos_private.fail('TAX_RATE_OVERLAP');
  end if;
  return new;
end;
$$;
create trigger tax_rates_overlap before insert or update on retailos.tax_rates
  for each row execute function retailos_private.tax_rates_no_overlap();

-- A rate that has been used is history: only its end date may change.
create or replace function retailos_private.tax_rates_frozen()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (new.tenant_id, new.tax_class_id, new.effective_from, new.gst_rate_pct)
     is distinct from (old.tenant_id, old.tax_class_id, old.effective_from, old.gst_rate_pct) then
    perform retailos_private.fail('TAX_RATE_IMMUTABLE');
  end if;
  return new;
end;
$$;
create trigger tax_rates_freeze before update on retailos.tax_rates
  for each row execute function retailos_private.tax_rates_frozen();

-- ---------------------------------------------------------------------------------------------
-- Categories, brands
-- ---------------------------------------------------------------------------------------------
create table retailos.categories (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references retailos.tenants (id) on delete restrict,
  name         text not null check (length(btrim(name)) > 0),
  product_kind text not null check (product_kind in ('CLOTHING', 'IMITATION_JEWELLERY', 'PRECIOUS_JEWELLERY')),
  hsn_code     text check (hsn_code is null or hsn_code ~ '^[0-9]{4,8}$'),
  tax_class_id uuid,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  unique (tenant_id, id),
  foreign key (tenant_id, tax_class_id) references retailos.tax_classes (tenant_id, id) on delete restrict
);
create unique index categories_name_idx on retailos.categories (tenant_id, lower(name));

create table retailos.brands (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null references retailos.tenants (id) on delete restrict,
  name       text not null check (length(btrim(name)) > 0),
  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  unique (tenant_id, id)
);
create unique index brands_name_idx on retailos.brands (tenant_id, lower(name));

-- ---------------------------------------------------------------------------------------------
-- Clothing: products (styles) and variants (size x colour)
-- ---------------------------------------------------------------------------------------------
create table retailos.products (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  category_id  uuid not null,
  brand_id     uuid,
  style_code   text not null check (length(btrim(style_code)) > 0),
  name         text not null check (length(btrim(name)) > 0),
  hsn_code     text check (hsn_code is null or hsn_code ~ '^[0-9]{4,8}$'),
  tax_class_id uuid,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (tenant_id, id),
  unique (tenant_id, style_code),
  foreign key (tenant_id, category_id) references retailos.categories (tenant_id, id) on delete restrict,
  foreign key (tenant_id, brand_id) references retailos.brands (tenant_id, id) on delete restrict,
  foreign key (tenant_id, tax_class_id) references retailos.tax_classes (tenant_id, id) on delete restrict
);
create trigger products_updated before update on retailos.products
  for each row execute function retailos_private.set_updated_at();

create or replace function retailos_private.products_clothing_only()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and retailos_private.has_any_permission(new.tenant_id, case when tg_op = 'INSERT' then 'product.create' else 'product.edit' end) is not true then
    perform retailos_private.fail('FORBIDDEN');
  end if;
  if not exists (select 1 from retailos.categories c
                 where c.tenant_id = new.tenant_id and c.id = new.category_id and c.product_kind = 'CLOTHING') then
    perform retailos_private.fail('VALIDATION_ERROR', jsonb_build_object('field', 'category'));
  end if;
  return new;
end;
$$;
create trigger products_kind before insert or update of category_id on retailos.products
  for each row execute function retailos_private.products_clothing_only();

create table retailos.product_variants (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null,
  product_id       uuid not null,
  sku              text not null check (length(btrim(sku)) > 0),
  size_label       text not null default 'FREE' check (length(btrim(size_label)) > 0),
  colour_label     text not null default 'DEFAULT' check (length(btrim(colour_label)) > 0),
  selling_price    numeric(14, 2) not null check (selling_price >= 0),
  mrp              numeric(14, 2) check (mrp is null or mrp >= selling_price),
  tax_class_id     uuid,
  reorder_level    integer check (reorder_level is null or reorder_level >= 0),
  is_active        boolean not null default true,
  price_updated_at timestamptz not null default now(),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (tenant_id, id),
  unique (tenant_id, sku),
  unique (product_id, size_label, colour_label),
  foreign key (tenant_id, product_id) references retailos.products (tenant_id, id) on delete restrict,
  foreign key (tenant_id, tax_class_id) references retailos.tax_classes (tenant_id, id) on delete restrict
);
create index product_variants_product_idx on retailos.product_variants (tenant_id, product_id);
create trigger product_variants_updated before update on retailos.product_variants
  for each row execute function retailos_private.set_updated_at();

-- Setting a price when creating a variant needs product.create. CHANGING an existing price needs
-- product.price_edit (owner by default). Who may change prices at all is an open client decision (OQ-38); until
-- decided, only the owner can.
create or replace function retailos_private.variant_price_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.selling_price is distinct from old.selling_price then
    if current_user in ('authenticated', 'anon') and retailos_private.has_any_permission(new.tenant_id, 'product.price_edit') is not true then
      perform retailos_private.fail('FORBIDDEN');
    end if;
    new.price_updated_at := now();
  end if;
  return new;
end;
$$;
create trigger product_variants_price_guard before update on retailos.product_variants
  for each row execute function retailos_private.variant_price_guard();

create table retailos.variant_costs (
  tenant_id  uuid not null,
  variant_id uuid not null,
  cost_price numeric(14, 2) not null check (cost_price >= 0),
  updated_at timestamptz not null default now(),
  primary key (variant_id),
  foreign key (tenant_id, variant_id) references retailos.product_variants (tenant_id, id) on delete restrict
);

-- ---------------------------------------------------------------------------------------------
-- Jewellery: designs and serialized items
-- ---------------------------------------------------------------------------------------------
create table retailos.jewellery_designs (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  kind         text not null check (kind in ('IMITATION', 'PRECIOUS')),
  category_id  uuid not null,
  design_code  text not null check (length(btrim(design_code)) > 0),
  name         text not null check (length(btrim(name)) > 0),
  hsn_code     text check (hsn_code is null or hsn_code ~ '^[0-9]{4,8}$'),
  tax_class_id uuid,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  unique (tenant_id, id),
  unique (tenant_id, design_code),
  unique (tenant_id, id, kind),
  foreign key (tenant_id, category_id) references retailos.categories (tenant_id, id) on delete restrict,
  foreign key (tenant_id, tax_class_id) references retailos.tax_classes (tenant_id, id) on delete restrict
);

create or replace function retailos_private.designs_kind_matches_category()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and retailos_private.has_any_permission(new.tenant_id, case when tg_op = 'INSERT' then 'product.create' else 'product.edit' end) is not true then
    perform retailos_private.fail('FORBIDDEN');
  end if;
  if not exists (
    select 1 from retailos.categories c
    where c.tenant_id = new.tenant_id and c.id = new.category_id
      and c.product_kind = case new.kind when 'IMITATION' then 'IMITATION_JEWELLERY' else 'PRECIOUS_JEWELLERY' end
  ) then
    perform retailos_private.fail('VALIDATION_ERROR', jsonb_build_object('field', 'category'));
  end if;
  return new;
end;
$$;
create trigger jewellery_designs_kind before insert or update of category_id, kind on retailos.jewellery_designs
  for each row execute function retailos_private.designs_kind_matches_category();

create table retailos.jewellery_items (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null,
  branch_id           uuid not null,
  design_id           uuid not null,
  kind                text not null check (kind in ('IMITATION', 'PRECIOUS')),
  tag_code            text not null check (tag_code ~ '^[A-Z0-9]{4,20}$'),
  status              text not null default 'IN_STOCK'
                      check (status in ('IN_STOCK', 'SOLD', 'QC_HOLD', 'DAMAGED', 'WRITTEN_OFF')),
  pricing_mode        text not null default 'FIXED_TAG' check (pricing_mode in ('FIXED_TAG', 'METAL_RATE')),
  tag_price           numeric(14, 2) check (tag_price is null or tag_price >= 0),
  metal_type          text,
  purity              text,
  gross_weight_g      numeric(12, 3),
  net_weight_g        numeric(12, 3),
  hallmark_huid       text,
  sold_invoice_item_id uuid,
  is_active           boolean not null default true,
  version             integer not null default 1,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (tenant_id, id),
  unique (tenant_id, tag_code),
  foreign key (tenant_id, branch_id) references retailos.branches (tenant_id, id) on delete restrict,
  foreign key (tenant_id, design_id, kind) references retailos.jewellery_designs (tenant_id, id, kind) on delete restrict,
  constraint fixed_tag_needs_price check (pricing_mode <> 'FIXED_TAG' or tag_price is not null),
  constraint imitation_is_fixed_tag check (kind = 'PRECIOUS' or pricing_mode = 'FIXED_TAG'),
  constraint precious_needs_metal_and_weights check (
    kind = 'IMITATION'
    or (metal_type is not null and purity is not null
        and gross_weight_g > 0 and net_weight_g > 0 and net_weight_g <= gross_weight_g)
  )
);
create index jewellery_items_branch_status_idx on retailos.jewellery_items (tenant_id, branch_id, status);
create trigger jewellery_items_updated before update on retailos.jewellery_items
  for each row execute function retailos_private.set_updated_at();

-- Once sold, nothing that determined the price may change.
create or replace function retailos_private.jewellery_item_sold_lock()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.status = 'SOLD' and (
       (new.kind, new.pricing_mode, new.tag_price, new.metal_type, new.purity, new.gross_weight_g, new.net_weight_g, new.design_id, new.tag_code)
       is distinct from
       (old.kind, old.pricing_mode, old.tag_price, old.metal_type, old.purity, old.gross_weight_g, old.net_weight_g, old.design_id, old.tag_code)
  ) then
    perform retailos_private.fail('ITEM_SOLD_LOCKED');
  end if;
  return new;
end;
$$;
create trigger jewellery_items_sold_lock before update on retailos.jewellery_items
  for each row execute function retailos_private.jewellery_item_sold_lock();

create table retailos.jewellery_item_costs (
  tenant_id  uuid not null,
  item_id    uuid not null,
  cost_price numeric(14, 2) not null check (cost_price >= 0),
  updated_at timestamptz not null default now(),
  primary key (item_id),
  foreign key (tenant_id, item_id) references retailos.jewellery_items (tenant_id, id) on delete restrict
);

-- ---------------------------------------------------------------------------------------------
-- Barcode registry. One table for every scannable code so uniqueness holds across variants and
-- jewellery items. Resolution is by EXACT equality only; there is deliberately no search function.
-- ---------------------------------------------------------------------------------------------
create table retailos.barcode_aliases (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  code              text not null,
  symbology         text not null default 'CODE128' check (symbology in ('CODE128', 'EAN13', 'UPCA', 'QR', 'OTHER')),
  target_type       text not null check (target_type in ('VARIANT', 'JEWELLERY_ITEM')),
  variant_id        uuid,
  jewellery_item_id uuid,
  is_primary        boolean not null default true,
  source            text not null default 'SYSTEM' check (source in ('SYSTEM', 'SUPPLIER', 'MANUAL')),
  is_active         boolean not null default true,
  created_at        timestamptz not null default now(),
  unique (tenant_id, code),
  check (code = upper(btrim(code)) and code ~ '^[A-Z0-9]{4,48}$'),
  check (num_nonnulls(variant_id, jewellery_item_id) = 1),
  check ((target_type = 'VARIANT') = (variant_id is not null)),
  foreign key (tenant_id, variant_id) references retailos.product_variants (tenant_id, id) on delete restrict,
  foreign key (tenant_id, jewellery_item_id) references retailos.jewellery_items (tenant_id, id) on delete restrict
);
create unique index barcode_primary_variant_idx on retailos.barcode_aliases (variant_id) where is_primary and variant_id is not null;
create unique index barcode_primary_item_idx on retailos.barcode_aliases (jewellery_item_id) where is_primary and jewellery_item_id is not null;

