-- ---------------------------------------------------------------------------------------------
-- Privileges and Row Level Security
-- ---------------------------------------------------------------------------------------------
-- New tables start with NO privileges for anon/authenticated (default privileges closed in M0001).
-- Everything below is an explicit grant.
grant select, insert, update on retailos.tax_classes, retailos.categories, retailos.brands, retailos.products,
  retailos.product_variants, retailos.jewellery_designs to authenticated;
grant select, insert on retailos.tax_rates to authenticated;
grant update (effective_to) on retailos.tax_rates to authenticated;
grant select, insert, update on retailos.variant_costs, retailos.jewellery_item_costs to authenticated;
-- jewellery items and barcodes are written only through functions (later increments); read-only here
grant select on retailos.jewellery_items to authenticated;
grant select, insert on retailos.barcode_aliases to authenticated;
grant update (is_active) on retailos.barcode_aliases to authenticated;

alter table retailos.tax_classes         enable row level security;
alter table retailos.tax_rates           enable row level security;
alter table retailos.categories          enable row level security;
alter table retailos.brands              enable row level security;
alter table retailos.products            enable row level security;
alter table retailos.product_variants    enable row level security;
alter table retailos.variant_costs       enable row level security;
alter table retailos.jewellery_designs   enable row level security;
alter table retailos.jewellery_items     enable row level security;
alter table retailos.jewellery_item_costs enable row level security;
alter table retailos.barcode_aliases     enable row level security;

-- Tax: read by the tenant, written with tax.manage (owner).
create policy tax_classes_read on retailos.tax_classes for select to authenticated using (retailos_private.has_any_permission(tenant_id, 'product.view'));
create policy tax_classes_write on retailos.tax_classes for insert to authenticated with check (retailos_private.has_tenant_permission(tenant_id, 'tax.manage'));
create policy tax_classes_update on retailos.tax_classes for update to authenticated
  using (retailos_private.has_tenant_permission(tenant_id, 'tax.manage')) with check (retailos_private.has_tenant_permission(tenant_id, 'tax.manage'));
create policy tax_rates_read on retailos.tax_rates for select to authenticated using (retailos_private.has_any_permission(tenant_id, 'product.view'));
create policy tax_rates_insert on retailos.tax_rates for insert to authenticated with check (retailos_private.has_tenant_permission(tenant_id, 'tax.manage'));
create policy tax_rates_update on retailos.tax_rates for update to authenticated
  using (retailos_private.has_tenant_permission(tenant_id, 'tax.manage')) with check (retailos_private.has_tenant_permission(tenant_id, 'tax.manage'));

-- Catalogue master data: read with product.view, created with product.create, edited with product.edit.
do $$
declare t text;
begin
  foreach t in array array['categories', 'brands', 'products', 'product_variants', 'jewellery_designs'] loop
    execute format('create policy %I on retailos.%I for select to authenticated using (retailos_private.has_any_permission(tenant_id, ''product.view''))', t || '_read', t);
    execute format('create policy %I on retailos.%I for insert to authenticated with check (retailos_private.has_any_permission(tenant_id, ''product.create''))', t || '_insert', t);
    execute format('create policy %I on retailos.%I for update to authenticated using (retailos_private.has_any_permission(tenant_id, ''product.edit'')) with check (retailos_private.has_any_permission(tenant_id, ''product.edit''))', t || '_update', t);
  end loop;
end $$;

-- Barcodes
create policy barcode_aliases_read on retailos.barcode_aliases for select to authenticated using (retailos_private.has_any_permission(tenant_id, 'product.view'));
create policy barcode_aliases_insert on retailos.barcode_aliases for insert to authenticated
  with check (retailos_private.has_any_permission(tenant_id, 'product.create'));
create policy barcode_aliases_update on retailos.barcode_aliases for update to authenticated
  using (retailos_private.has_any_permission(tenant_id, 'product.edit')) with check (retailos_private.has_any_permission(tenant_id, 'product.edit'));

-- Costs: hidden from anyone without cost.view; written with cost.manage (owner).
create policy variant_costs_read on retailos.variant_costs for select to authenticated using (retailos_private.has_any_permission(tenant_id, 'cost.view'));
create policy variant_costs_insert on retailos.variant_costs for insert to authenticated with check (retailos_private.has_tenant_permission(tenant_id, 'cost.manage'));
create policy variant_costs_update on retailos.variant_costs for update to authenticated
  using (retailos_private.has_tenant_permission(tenant_id, 'cost.manage')) with check (retailos_private.has_tenant_permission(tenant_id, 'cost.manage'));
create policy jewellery_item_costs_read on retailos.jewellery_item_costs for select to authenticated using (retailos_private.has_any_permission(tenant_id, 'cost.view'));
create policy jewellery_item_costs_insert on retailos.jewellery_item_costs for insert to authenticated with check (retailos_private.has_tenant_permission(tenant_id, 'cost.manage'));
create policy jewellery_item_costs_update on retailos.jewellery_item_costs for update to authenticated
  using (retailos_private.has_tenant_permission(tenant_id, 'cost.manage')) with check (retailos_private.has_tenant_permission(tenant_id, 'cost.manage'));

-- Jewellery items: visible only in branches the user can access.
create policy jewellery_items_read on retailos.jewellery_items for select to authenticated
  using (retailos_private.has_any_permission(tenant_id, 'product.view') and retailos_private.has_branch_access(branch_id));
